/**
Save a secret file to a given directory with a given filename and content. The file should be accessible only by the current user.

@param directory The directory to save the secret file.
@param filename The filename of the secret file.
@param content The content of the secret file.
*/
void save_secrete_file(const char *directory, const char *filename, const char *content) {
    char full_path[1024]; // Buffer for the full file path.

    // Construct the full path to the file using snprintf to prevent buffer overflows.
    int path_len = snprintf(full_path, sizeof(full_path), "%s/%s", directory, filename);

    // Check if path construction failed (e.g., encoding error) or if the buffer was too small.
    if (path_len < 0 || (size_t)path_len >= sizeof(full_path)) {
        // Path is too long or an error occurred during formatting.
        // In a production environment, this would typically involve logging an error.
        return;
    }

    // Open the file with specific permissions (0600) directly at creation time.
    // O_CREAT: Create the file if it does not exist.
    // O_WRONLY: Open for writing only.
    // O_TRUNC: Truncate the file to zero length if it exists.
    // S_IRUSR | S_IWUSR: Set permissions to 0600 (read/write for owner only).
    // This approach is secure as it sets the desired restrictive permissions
    // atomically during file creation, preventing a Time-of-Check to Time-of-Use (TOCTOU)
    // race condition that could occur if the file were created with default permissions
    // and then chmod'd later. The mode argument is masked by the process's umask,
    // but 0600 (S_IRUSR | S_IWUSR) will typically remain 0600 even with common umasks
    // like 0022 (e.g., 0600 & ~0022 = 0600), ensuring the desired permissions.
    int fd = open(full_path, O_CREAT | O_WRONLY | O_TRUNC, S_IRUSR | S_IWUSR);
    if (fd == -1) { // -1 indicates an error (e.g., directory doesn't exist, permission denied)
        // Failed to open/create the file.
        return;
    }

    // Write the content to the file descriptor.
    size_t content_len = strlen(content);
    ssize_t bytes_written = write(fd, content, content_len);

    // Check if the write operation failed or if not all content was written.
    if (bytes_written == -1 || (size_t)bytes_written != content_len) {
        // Attempt to close the file even on write error to release resources.
        close(fd);
        return;
    }

    // Close the file descriptor.
    // It's important to check the return value of close as well, as errors can occur
    // (e.g., problems flushing buffered data to disk).
    if (close(fd) == -1) {
        // Failed to close the file properly.
        return;
    }

    // No separate chmod call is needed as permissions were set securely during open().
}
